    local n = tokens >= 5 and 5 or (tokens >= 1 and 1 or (spare >= cost * 5 and 5 or (spare >= cost and 1 or 0)))
    if n > 0 then
        local r = M.inv("RollMutation", n)
        if type(r) == "table" and r.ok then S.rolls += n LOG("rolled", n) end
    end
    if on("p_equip") then
        local owned = M.json("Mutations")
        local list = {}
        for key, stars in pairs(owned) do if D.C.MutationByKey and D.C.MutationByKey[key] then list[#list + 1] = { key = key, score = F.rarityRank(key) * 10 + (tonumber(stars) or 1) } end end
        table.sort(list, function(a, b) return a.score > b.score end)
        local eq = M.json("Equipped")
        local slots = M.attr("Slots", 1)
        local wanted, isEq = {}, {}
        for i = 1, slots do if list[i] then wanted[list[i].key] = true end end
        for i = 1, slots do if eq[i] and eq[i] ~= "" then isEq[eq[i]] = true end end
        for i = 1, slots do
            local cur = eq[i]
            if not (cur and wanted[cur]) then
                for _, e in ipairs(list) do
                    if wanted[e.key] and not isEq[e.key] then
                        local r = M.inv("EquipMutation", e.key, i)
                        LOG("equip mutation", e.key, i, type(r) == "table" and tostring(r.ok) or "")
                        break
                    end
                end
                break
            end
        end
    end
end
function F.pets()
    if not on("p_pets") or not D.C then return end
    local dna = M.attr("DNA", 0) - M.reserve()
    local eggs = D.C.Pets and D.C.Pets.Eggs or D.C.Eggs
    local best
    local top
    for _, e in ipairs(type(eggs) == "table" and eggs or {}) do
        if e.cost and not e.robux then
            if not top or e.cost > top.cost then top = e end
            if e.cost <= dna and (not best or e.cost > best.cost) then best = e end
        end
    end
    if best and top and best ~= top and #M.json("PetsOwned") >= 3 then best = nil end
    if best then
        local r = M.inv("HatchPet", best.key)
        if type(r) == "table" and r.ok then S.hatches += 1 LOG("hatch", best.key) M.inv("EquipPet", "best") end
    end
end
F.codeDone = {}
F.rewAt = 0
function F.rewards()
    if not on("r_on") or os.clock() - F.rewAt < 60 or not D.C then return end
    F.rewAt = os.clock()
    for code in pairs(D.C.Codes or {}) do
        if not F.codeDone[code] then
            local r = M.inv("Redeem", code)
            F.codeDone[code] = true
            if type(r) == "table" and r.ok then S.rewards += 1 LOG("code", code) end
            task.wait(1)
        end
    end
    if (M.attr("DailyNext", 0) or 0) <= Workspace:GetServerTimeNow() then
        local r = M.inv("ClaimDaily")
        if type(r) == "table" and r.ok then S.rewards += 1 LOG("daily") end
    end
    local claimed = {}
    for _, v in ipairs(M.json("PlaytimeClaimed")) do claimed[tonumber(v) or v] = true end
    local ps = M.attr("PlayStart", 0) or 0
    local played = ps > 0 and (Workspace:GetServerTimeNow() - ps) / 60 or 0
    for i, p in ipairs(D.C.Playtime or {}) do
        if not claimed[i] and played >= (p.minutes or 1e9) then
            local r = M.inv("ClaimPlaytime", i)
            if type(r) == "table" and r.ok then S.rewards += 1 LOG("playtime", i) end
        end
    end
    local qs = M.json("Quests")
    local allDone = true
    for i, q in ipairs(qs.q or {}) do
        local goal, prog, cl = tonumber(q[3]) or 1e18, tonumber(q[4]) or 0, tonumber(q[5]) or 0
        if cl == 0 then allDone = false end
        if prog >= goal and cl == 0 then
            local r = M.inv("ClaimQuest", i)
            if type(r) == "table" and r.ok then S.rewards += 1 LOG("quest", i) end
        end
    end
    if allDone and (tonumber(qs.b) or 0) == 0 and qs.q and #qs.q > 0 then
        local r = M.inv("ClaimQuest", "bonus")
        if type(r) == "table" and r.ok then S.rewards += 1 LOG("quest bonus") end
    end
    local recs = M.json("Records")
    for i, rec in ipairs(D.C.Records and D.C.Records.List or {}) do
        local st = recs[i]
        local tier, prog = st and tonumber(st[1]) or 0, st and tonumber(st[2]) or 0
        local goal = rec.goals and rec.goals[tier + 1]
        if goal and prog >= goal then
            local r = M.inv("ClaimRecord", rec.key)
            if type(r) == "table" and r.ok then S.rewards += 1 LOG("record", rec.key) end
        end
    end
    if not M.attr("CommunityClaimed", false) then
        local gid = D.C.Community and D.C.Community.GroupId or D.C.GroupId
        local inG = gid and M.call(function() return lp:IsInGroup(gid) end)
        if inG then local r = M.inv("CommunityClaim") if type(r) == "table" and r.ok then S.rewards += 1 end end
    end
end
