function F.eventStep()
    if not on("ev_on") or not M.alive() then return false end
    local now = F.now()
    local e = F.evt
    if e.gold and now >= e.gold.at - 2 and now <= e.gold.at + 4 then
        S.task = __T["Catching the gold star"] S.taskAt = os.clock()
        local r = M.root()
        if not r or (r.Position - e.gold.o).Magnitude > 5 then F.stand(e.gold.o) end
        return true
    elseif e.gold and now > e.gold.at + 4 then e.gold = nil end
    local bestId, best, bd
    local r = M.root()
    for id, l in pairs(e.loot) do
        if l.ends and now > l.ends then e.loot[id] = nil
        elseif r then local d = (l.o - r.Position).Magnitude if not bd or d < bd then bestId, best, bd = id, l, d end end
    end
    if best then
        S.task = __T["Grabbing storm crystals"] S.taskAt = os.clock()
        F.stand(best.o)
        task.wait(0.4)
        e.loot[bestId] = nil
        return true
    end
    if e.race then
        if e.race.ends and now > e.race.ends then e.race = nil else
            S.task = __T["Winning the race"] S.taskAt = os.clock()
            if not r or Vector2.new(r.Position.X - e.race.goal.X, r.Position.Z - e.race.goal.Z).Magnitude > 10 then F.stand(e.race.goal) end
            return true
        end
    end
    if e.hunt then
        if e.hunt.ends and now > e.hunt.ends then e.hunt = nil else
            local pl = Players:GetPlayerByUserId(tonumber(e.hunt.id) or 0)
            local c = pl and pl.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            local id = c and c:GetAttribute("EntityId")
            if hrp and id then
                S.task = __T["Hunting the admin"] S.taskAt = os.clock()
                local depth = F.depthFor(c)
                F.groundY(c, hrp.Position)
                M.hold(F.underCF(c, hrp, depth), function() return F.underCF(c, hrp, depth) end)
                M.fire("Bite", id)
                task.wait(0.5)
                return true
            end
        end
    end
    if on("ev_sugar") then
        local st = ReplicatedStorage:FindFirstChild("AntState")
        if st and st:GetAttribute("Event") == "SugarRush" and (tonumber(st:GetAttribute("EventEnd")) or 0) > now then
            local ok, data = pcall(function() return HttpService:JSONDecode(st:GetAttribute("EventData") or "{}") end)
            local cube = ok and type(data) == "table" and vec(data.cube)
            if cube then
                S.task = "Sugar Rush" S.taskAt = os.clock()
                local ring = (tonumber(data.ring) or 20) * 0.6
                if not r or Vector2.new(r.Position.X - cube.X, r.Position.Z - cube.Z).Magnitude > ring then F.stand(cube) end
                return true
            end
        end
    end
    return false
end
function F.threats(myL)
    local out = {}
    local ants = Workspace:FindFirstChild("Ants")
    local function add(m)
        local hrp = m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart)
        if hrp and not m:GetAttribute("Dead") then
            local L = tonumber(m:GetAttribute("Length")) or 3
            out[#out + 1] = { pos = hrp.Position, reach = F.reach(L, myL) + 6 }
        end
    end
    for _, pl in ipairs(Players:GetPlayers()) do if pl ~= lp and pl.Character then add(pl.Character) end end
    for _, f in ipairs({ ants and ants:FindFirstChild("Bots"), ants and ants:FindFirstChild("Critters") }) do
        for _, m in ipairs(f and f:GetChildren() or {}) do
            local def = D.C and D.C.Critters and D.C.Critters[m:GetAttribute("Species") or ""]
            if f.Name == "Bots" or (def and def.aggressive) then add(m) end
        end
    end
    return out
end
function F.safePos(myL)
    local th = F.threats(myL)
    local function clear(p)
        local worst = math.huge
        for _, t in ipairs(th) do
            local d = Vector2.new(p.X - t.pos.X, p.Z - t.pos.Z).Magnitude - t.reach
            if d < worst then worst = d end
        end
        return worst
    end
    local cands = {}
    for _, o in pairs(F.orbs) do cands[#cands + 1] = o.pos if #cands > 400 then break end end
    local L = D.Layout
    if L and L.spawn then cands[#cands + 1] = L.spawn.center end
    local best, bs
    for _, p in ipairs(cands) do local c = clear(p) if not bs or c > bs then best, bs = p, c end end
    return best, bs or 0, th
end
function F.heal()
    local c = lp.Character
    if not c then return end
    S.task = __T["Healing safely"] S.taskAt = os.clock() S.escapes += 1
    local myL = tonumber(c:GetAttribute("Length")) or 3
    local moves = 0
    local function relocate()
        moves += 1
        local spot, clearance, th = F.safePos(myL)
        local maxReach = 0
        for _, t in ipairs(th) do if t.reach > maxReach then maxReach = t.reach end end
        local depth = math.clamp(math.max(18, myL * 1.5, (clearance < 0 and maxReach + 8) or 0), 18, 120)
        spot = spot or M.root().Position
        M.release()
        local g = M.ground(spot)
        local gy = g and g.Y or spot.Y
        local holdY = math.max(math.min(gy, spot.Y, 0) - depth, -400)
        M.hold(CFrame.new(spot.X, holdY, spot.Z), nil, gy)
        LOG("heal hide", moves, math.floor(depth), math.floor(clearance))
    end
    relocate()
    local t0 = os.clock()
    local last = tonumber(c:GetAttribute("HP")) or 0
    while RUNNING and M.alive() and os.clock() - t0 < (F.healTime or 40) do
        task.wait(0.5)
        local hp, mx = tonumber(c:GetAttribute("HP")) or 0, tonumber(c:GetAttribute("MaxHP")) or 1
        if hp / mx >= (F.healTo or 0.9) then break end
        if hp < last - mx * 0.01 and moves < 6 then relocate() end
        last = hp
    end
    M.release()
end
function F.danger()
    local c = lp.Character
    if not c then return false end
    local hp, mx = tonumber(c:GetAttribute("HP")) or 1, tonumber(c:GetAttribute("MaxHP")) or 1
    return hp / mx < (tonumber(val("s_hp", 50)) or 50) / 100
end
function F.mainLoop()
    local n = 0
    while RUNNING do
        n += 1
        local ok = pcall(function()
            if F.respawn() then task.wait(0.5) return end
            if on("s_escape") and F.danger() then
                pcall(F.heal)
                return
            end
            if os.clock() < (F.pauseUntil or 0) then return end
            F.evolve()
            if os.clock() < (F.pauseUntil or 0) then return end
            local evOk, evDid = pcall(F.eventStep)
            if evOk and evDid then task.wait(0.2) return end
            if F.lostEggs() then return end
            local did = false
            if on("f_orbs") then for _ = 1, (on("h_on") and 3 or 1) do if F.orbHop() then did = true end end end
            if on("h_on") and (n % 2 == 0 or not did) then if F.hunt() then did = true end end
            if not did then M.release() task.wait(0.5) end
        end)
        if not ok then M.holdCF = nil end
        task.wait(0.05)
    end
end
function F.slowLoop()
    while RUNNING do
