    if not L then return end
    local pos
    if name == "Spawn" then pos = L.spawn and L.spawn.center
    else
        for _, z in ipairs(L.zones and L.zones.list or {}) do
            if z.id == name then
                local b = math.rad((z.bearing_from + z.bearing_to) / 2)
                local r = ((L.zones.inner_radius or 260) + (L.zones.outer_radius or 640)) / 2
                local c = L.center or Vector3.zero
                pos = Vector3.new(c.X + math.sin(b) * r, c.Y + 20, c.Z - math.cos(b) * r)
            end
        end
    end
