    SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg", "p_tp" })
    ThemeManager:SetFolder("COMBO_WICK_ANTEVO")
    SaveManager:SetFolder("COMBO_WICK_ANTEVO")
    ThemeManager:ApplyToTab(Tab)
    SaveManager:BuildConfigSection(Tab)
end)
