            local evName = st and st:GetAttribute("Event")
            local left = st and math.floor((tonumber(st:GetAttribute("EventEnd")) or 0) - now) or 0
            local okD, ed = pcall(function() return HttpService:JSONDecode(st:GetAttribute("EventData") or "{}") end)
            local nice = okD and type(ed) == "table" and (ed.name or ed.title) or nil
            if not nice and evName then nice = tostring(evName):gsub("(%l)(%u)", "%1 %2") end
            local evLine = (evName and evName ~= "" and left > 0) and string.format(__T["<b>%s</b> · %ds left"], tostring(nice), left) or __T["No event right now"]
            local gs = st and tonumber(st:GetAttribute("GoldenStart")) or 0
            local ge = st and tonumber(st:GetAttribute("GoldenEnd")) or 0
            local gold = (now >= gs and now < ge) and string.format(__T["Golden Hour · %dm left"], math.floor((ge - now) / 60)) or (gs > now and string.format(__T["Golden Hour in %dm"], math.floor((gs - now) / 60)) or __T["Golden Hour soon"])
            local host = st and tonumber(st:GetAttribute("HostAt")) or 0
            local adm = (host > 0 and host > now) and string.format(__T["\nAdmin event in %dm"], math.floor((host - now) / 60)) or ""
            setText(UI.r1, evLine .. "\n" .. gold .. adm .. string.format(__T["\nEggs found %d · Rewards %d"], S.eggs, S.rewards))
            setText(UI.p1, string.format(__T["Rebirth <b>%s</b> · Stage %s\nEvolves %d · Rebirths %d\nRolls %d · Pets %d"], tostring(M.attr("Rebirths", 0)), tostring(M.attr("Stage", 1)), S.evolves, S.rebirths, S.rolls, S.hatches))
        end)
        task.wait(0.5)
    end
end)
